import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>تحتاج أن تعرف كم حجم صورة حقًا، بالبكسلات، قبل رفعها أو طباعتها أو تسليمها لعميل. اسم الملف لن يخبرك، والمصغرة تخدع.</p>\n<p>هذا الدليل يُظهر لك كيف تتحقق من أبعاد صورة في خمس خطوات، لصورة واحدة أو لدفعة كاملة. يستغرق نحو دقيقة، وستنتهي بتقرير تستطيع مشاركته.</p>\n<p>لا برنامج للتثبيت ولا حساب للإنشاء ولا شيء يُرفع إلى أي مكان: صورك تُقرأ محليًا في متصفحك من البداية إلى النهاية.</p>\n<h2 id=\"what-you-need\">ما تحتاجه قبل أن تبدأ</h2>\n<p>تحتاج ملفات الصور على حاسوبك أو هاتفك: ملفات JPG وPNG وWebP وGIF وBMP وHEIC وSVG تعمل، حتى 20 MB لكل ملف.</p>\n<p>وإذا كان لديك متطلب منصة، دوّنه أولًا: عرض أدنى أو نسبة مطلوبة أو حجم طباعة مستهدف يمنح المراجعة معيار نجاح أو فشل بدل التخمين. والمتصفح هو كل البرامج التي تحتاجها: Chrome وSafari وFirefox وEdge تشغّل الأداة، على الحاسوب والهاتف، دون أي إضافة.</p>\n<p>ولمراجعة دفعة، اجمع الملفات في مجلد قبل أن تبدأ: إسقاط مجلد أسرع من البحث عن الملفات واحدًا واحدًا بينما الجدول نصف مبني.</p>\n<h2 id=\"step-1-upload-a-batch\">الخطوة 1: ارفع صورة أو دفعة كاملة</h2>\n<p>افتح <a href=\"/ar/fahis-abad-as-sura/\">فاحص أبعاد الصورة</a> واسحب ملفاتك إلى منطقة الرفع: يمكنك إسقاط صورة واحدة أو مجلد كامل دفعة واحدة.</p>\n<p>ويمكنك أيضًا النقر على منطقة الرفع للتصفح، أو لصق صورة من الحافظة بـCtrl+V لمراجعة لقطة التقطتها للتو. ويبدأ الجدول بالامتلاء مع قراءة كل ملف: كل صف يُظهر اسم الملف والأبعاد بالبكسلات والنسبة والميغابكسلات وحجم الملف والحالة.</p>\n<p>وإذا كان لديك ملفات أكثر لإضافتها لاحقًا، أسقطها فتنضم إلى الجدول الموجود: تضيف الأداة صفوفًا جديدة بدل مسح ما لديك.</p>\n<h2 id=\"step-2-read-the-table\">الخطوة 2: اقرأ جدول الأبعاد</h2>\n<p>ابدأ بعمود الأبعاد: يُظهر العرض في الارتفاع بالبكسلات، مثل 1920 في 1080، وذلك الزوج هو أهم رقم في التقرير كله.</p>\n<p>قارن العرض والارتفاع بمتطلبك: إذا أرادت منصتك 1000 بكسل عرضًا على الأقل والصورة بها 800، فهي لا تجتاز، مهما بدت جيدة. ثم ألقِ نظرة على عمود الميغابكسلات: يخبرك إجمالي عدد البكسلات بنظرة، ما يساعد عندما تقارن صورتين بشكلين مختلفين لكن حجم متشابه.</p>\n<p>وأخيرًا، راجع عمود حجم الملف: ملف صغير جدًا بأبعاد كبيرة قد يكون مضغوطًا بشدة، وهي علامة تحذير لعمل الطباعة حتى لو بدا جيدًا على الشاشة.</p>\n<h2 id=\"step-3-check-the-ratio\">الخطوة 3: راجع النسبة</h2>\n<p>يُظهر عمود النسبة شكل كل صورة، مثل 16:9 أو 4:3 أو 1:1. ويُظهر أيضًا النسبة الدقيقة عندما لا تطابق صورة شكلًا معياريًا.</p>\n<p>طابق النسبة مع وجهتك: عمودي 4:5 يملأ خلاصة هاتف أفضل من مربع، بينما أفقي 16:9 يناسب مصغرة فيديو أو صورة رئيسية. وانتبه للتقريبات: صورة 1.48:1 تبدو شبه مربعة لكنها ليست 3:2، ومنصة تقص إلى 3:2 ستقطع الحواف بطرق لم تخطط لها.</p>\n<p>وإذا كانت النسبة خطأ، قص الصورة قبل أي شيء آخر: <a href=\"/ar/qass-as-suwar/\">قاص الصور</a> يقطع إلى النسبة الدقيقة التي تحتاجها، والفاحص يؤكد النتيجة بعدها.</p>\n<h2 id=\"step-4-validate-minimums\">الخطوة 4: تحقق مع العرض والارتفاع الأدنى</h2>\n<p>اكتب حدود منصتك الدنيا في حقلي فحص العرض الأدنى والارتفاع الأدنى: توسّم الأداة كل صورة تقع دون أي من الرقمين.</p>\n<p>الصفوف الموسومة هي قائمة مهامك: كل واحدة تحتاج ملف مصدر أكبر أو تغيير حجم أو قرار بقبول جودة أدنى. ولا تكبّر صورة موسومة وتفترض أن المشكلة حُلت: التكبير يخترع بكسلات، فيجتاز الملف الفحص العددي بينما يبدو أنعم من صورة عالية الدقة.</p>\n<p>وعندما لا يمكن تكبير ملف مصدر، تحدث مع الشخص الذي سلّمه: مصور أو مصمم لديه الأصل غالبًا يستطيع تصدير نسخة أكبر في ثوانٍ.</p>\n<h2 id=\"step-5-export-the-report\">الخطوة 5: صدّر التقرير كـCSV أو JSON</h2>\n<p>عندما يكتمل الجدول، انقر تصدير CSV لجدول بيانات أو تصدير JSON لملف بيانات منظمة: كلاهما يحتوي نفس أعمدة الجدول على الشاشة.</p>\n<p>يفتح CSV في Excel أو Google Sheets، حيث تستطيع الفرز حسب العرض أو التصفية حسب النسبة أو إبراز الصفوف الموسومة لزميل ليصححها. وJSON للمطورين وسير العمل الآلي: يحمل نفس البيانات بصيغة يستطيع سكربت قراءتها، ما يناسب أنظمة المحتوى ولوحات الجودة.</p>\n<p>صدّر قبل إغلاق التبويب، لأن الجدول يعيش فقط في متصفحك: تحديث يمسحه، وإعادة مراجعة دفعة كبيرة مضيعة للوقت.</p>\n<h2 id=\"checking-one-image\">كيف تراجع صورة واحدة بسرعة</h2>\n<p>لصورة واحدة، العملية نفسها لكنها أسرع: أسقط الملف واقرأ صف الأبعاد وانتهِ في أقل من عشر ثوانٍ.</p>\n<p>اللصق هو أسرع طريق من كل شيء للقطات: انسخ لقطة شاشة واضغط Ctrl+V في الأداة فتظهر الأبعاد دون حفظ أي ملف. وعلى الهاتف، ارفع الصورة من معرضك: يعمل الجدول على شاشات صغيرة، والأرقام الرئيسية تُرى دون تمرير جانبي.</p>\n<p>ومراجعة صورة واحدة هي أيضًا أسرع طريقة لحسم جدال: عندما يختلف شخصان على إن كانت صورة كبيرة بما يكفي، يعطي الفاحص رقمًا يحسم الأمر.</p>\n<h2 id=\"reading-the-print-size\">كيف تقرأ عمود حجم الطباعة</h2>\n<p>يحوّل عمود الطباعة عند 300 DPI البكسلات إلى بوصات بجودة طباعة: صورة بعرض 3000 بكسل تُعرض 10 بوصات، وهو عرضها الآمن المطبوع.</p>\n<p>قارن ذلك الرقم بالحجم الذي تحتاجه فعلًا: إذا احتجت طباعة 8 بوصات ويقول العمود 4 بوصات، فستبدو الصورة ناعمة عند تمديدها لتناسب. وتذكر أن 300 DPI معيار جودة لا قانون: ملصق يُرى من عبر القاعة يمكن طباعته جيدًا عند 150 DPI، بينما نشرة تُمسك باليد تحتاج 300.</p>\n<p>ولأسئلة الطباعة عمومًا، يستطيع <a href=\"/ar/taghyir-dpi-as-sura/\">مغيّر DPI الصورة</a> تثبيت بيانات DPI الوصفية لملفاتك بمجرد أن تعرف أن البكسلات كافية.</p>\n<h2 id=\"spotting-misleading-extensions\">كيف تكتشف امتدادات ملفات مضللة</h2>\n<p>ملف اسمه .jpg ليس دائمًا JPEG: الناس يغيّرون أسماء الملفات، وبعض الأنظمة تحفظ WebP بامتداد .jpg خطأ.</p>\n<p>يقرأ الفاحص بيانات الصورة الحقيقية، لا الامتداد: إذا تبين أن JPG مزعوم هو WebP، تُبلغ الأداة بما هو الملف حقًا. وهذا مهم لأن بعض المنصات ترفض ملفات لا يطابق محتواها امتدادها: اكتشاف الفرق في الفاحص يمنع رفعًا فاشلًا لاحقًا.</p>\n<p>وإذا وجدت ملفًا مسمى خطأ، حوّله بشكل صحيح بدل إعادة تسميته مجددًا: <a href=\"/ar/tahwil-as-suwar/\">محوّل الصور</a> يكتب ملفًا صحيحًا بالصيغة والامتداد المناسبين.</p>\n<h2 id=\"checking-svg-files\">كيف تراجع ملفات SVG</h2>\n<p>ملفات SVG متجهات، فيقرأ الفاحص أبعادها الجوهرية من سمات العرض والارتفاع وviewBox بدل عد البكسلات.</p>\n<p>الحجم الجوهري هو الحجم الذي قصده المصمم: يمكن لـSVG أن يتكبر أبعد بكثير دون فقدان حدة، لكن الحجم المقصود يخبرك بالنسب التي يجب الحفاظ عليها. وإذا كان لـSVG viewBox لكن لا عرض ولا ارتفاع، يُظهر الفاحص النسبة دون أبعاد مطلقة: هذا طبيعي في أيقونات متجاوبة مصممة للتكبير.</p>\n<p>وللأيقونات، قارن نسبة SVG بتصميمك: viewBox 0 0 24 24 مربع، ووضعه في مساحة عريضة سيمدده أو يترك مساحة فارغة.</p>\n<h2 id=\"troubleshooting-unreadable-files\">حل المشاكل: ملفات لا يمكن قراءتها</h2>\n<p>أحيانًا لا يُقرأ ملف إطلاقًا، وتوسّمه الأداة كخطأ: السبب الشائع تنزيل تالف أو ملف ليس صورة حقًا.</p>\n<p>جرّب فتح الملف أولًا في عارض صور: إذا فشل العارض أيضًا، فالملف تالف ويحتاج تنزيلًا مجددًا أو تصديرًا مجددًا من مصدره. وملف أكبر من 20 MB سيُرفض أيضًا: اضغطه أو غيّر حجمه أولًا، ثم راجع النسخة الأصغر، لأن أبعاد الملف المغيّر الحجم هي التي ستستخدمها.</p>\n<p>ملف تالف لا يحجب بقية الدفعة أبدًا: يبلغ الفاحص عن صف الخطأ ويستمر في قراءة الملفات المتبقية، فتستطيع إصلاح التالف بعدها.</p>\n<h2 id=\"fixing-a-failed-image\">كيف تصلح صورة لم تجتز المراجعة</h2>\n<p>ابدأ بالمصدر: اطلب التصدير الأصلي بحجم أكبر قبل تجربة أي إصلاح برمجي، لأن ملفًا عالي الدقة حقيقيًا يتفوق على أي نسخة مكبرة.</p>\n<p>وإذا كانت النسبة خطأ، قصها: <a href=\"/ar/qass-as-suwar/\">قاص الصور</a> يقطع إلى النسبة الدقيقة التي تريدها منصتك، ومراجعة جديدة تؤكد الأبعاد الجديدة. وإذا كان الملف صغيرًا جدًا ولا يوجد مصدر أكبر، غيّر حجمه بـ<a href=\"/ar/taghyir-hajm-as-suwar/\">مغيّر حجم الصور</a> واقبل النعومة: إنه أفضل من عدم اجتياز الرفع، لكن كن صادقًا مع العميل بشأن المقايضة.</p>\n<p>أعد المراجعة بعد كل إصلاح: تمريرة ثانية عبر الفاحص تؤكد الأبعاد الجديدة وتمنحك تقريرًا نظيفًا تحفظه مع العمل المنجز.</p>\n<h2 id=\"sharing-the-report\">كيف تشارك التقرير مع فريقك</h2>\n<p>تقرير CSV هو الأسهل مشاركة: أرسله إلى المصمم أو المطور أو العميل، ويرى الجميع نفس الأرقام بدل الجدال من الذاكرة.</p>\n<p>أبرز الصفوف الموسومة قبل إرساله: تقرير بفشل موسوم بوضوح يُصحح أسرع من جدول خام يجبر القارئ على البحث عن المشاكل. وللعمل المتكرر، اتفقوا على حجم أدنى مرة واحدة واكتبوه: كل دفعة مستقبلية تُراجع بنفس المعيار، وتصبح التقارير قابلة للمقارنة مع الوقت.</p>\n<p>احفظ التقارير القديمة في مجلد المشروع: عندما تغيّر منصة متطلباتها، يُظهر التقرير القديم أي صور كانت تفي قبلًا وأيها يحتاج مراجعة مجددًا الآن.</p>\n<h2 id=\"checking-before-print\">كيف تراجع الأبعاد قبل طلب طباعة</h2>\n<p>طلبات الطباعة هي أغلى مكان لاكتشاف مشكلة أبعاد، لأن الخطأ لا يُرى إلا بعد طباعة العمل ودفع ثمنه: مراجعة دقيقتين قبلها هي أرخص تأمين.</p>\n<p>ابدأ بسؤال المطبعة عن الحجم النهائي بالبوصات وDPI التي تريدها، غالبًا 300: اضرب البوصات في DPI للحصول على أبعاد البكسلات التي تحتاجها. ومرّر صورك عبر الفاحص وقارن كلًا منها بذلك الهدف: أي صورة لا تصل ستُطبع ناعمة، والفرق يخبرك بالضبط كم أصغر يجب أن تكون الطباعة.</p>\n<p>انتبه أيضًا إلى النسبة، لا الحجم فقط: مطبعة تقص إلى نسبة ثابتة ستقص صورتك، فتأكد من أن التفاصيل المهمة تبقى آمنة داخل القص. وراجع صيغة الملف في نفس الوقت: المطابع تفضل JPG أو TIFF للصور وPDF أو PNG للرسوم، وملف بصيغة خطأ قد يسبب تأخيرًا حتى لو كانت الأبعاد صحيحة.</p>\n<p>وأخيرًا، صدّر التقرير وأرسله إلى المطبعة مع الملفات: مطبعة تستطيع رؤية جدول الأبعاد ستكتشف مشكلة قبل أن تعمل المطبعة، وهو أفضل بكثير من اكتشافها بعدها.</p>\n<h2 id=\"recurring-batch-checks\">كيف تجعل مراجعة الأبعاد عادة</h2>\n<p>المراجعات المنفردة تكتشف مشاكل منفردة، لكن معظم فشل الأبعاد يتكرر: نفس المورد يرسل صورًا صغيرة كل شهر، أو نفس القالب يصدّر بنسبة خطأ.</p>\n<p>ادمج المراجعة في سير عملك بدل معاملتها كخطوة طارئة: مرّر كل دفعة صور جديدة عبر الفاحص لحظة وصولها، قبل أن يبدأ أحد باستخدامها. واحتفظ بسجل بسيط لما فشل ولماذا: بعد أسابيع قليلة يصبح النمط واضحًا، وتستطيع إصلاح المصدر — ضبط تصدير خطأ أو مورد مهمل أو قالب قديم.</p>\n<p>شارك العادة مع الفريق: عندما يراجع الجميع الأبعاد قبل تسليم الملفات، يتوقف الفشل عن الوصول في اللحظة الأخيرة، ويصبح الفاحص خطوة خلفية هادئة.</p>\n<h2 id=\"quick-reference-checklist\">قائمة مرجعية سريعة</h2>\n<p>أسقط الملفات واقرأ عمود الأبعاد أولًا، ثم النسبة، وبعدها الميغابكسلات وحجم الملف كسياق.</p>\n<p>اكتب عرضك وارتفاعك الأدنى، ووسّم الفشل، وأصلحه من ملف المصدر كلما أمكن بدل التكبير. وراجع عمود حجم الطباعة قبل إرسال أي شيء للطباعة، وصدّر تقرير CSV أو JSON قبل إغلاق التبويب.</p>\n<p>للسياق الكامل، اقرأ <a href=\"/ar/blog/dalil-fahis-abad-as-suwar/\">دليل فاحص أبعاد الصور الكامل</a>، وللنظرية وراء الأرقام راجع <a href=\"/ar/blog/al-abad-vs-al-diqqa-vs-hajm-al-malaf/\">الأبعاد مقابل الدقة مقابل حجم الملف موضحة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أراجع أبعاد صورة على هاتفي؟","answer":"افتح فاحص الأبعاد في متصفح هاتفك وارفع الصورة من معرضك: يُظهر الجدول العرض والارتفاع والنسبة والميغابكسلات. ويمكنك أيضًا لصق لقطة شاشة مباشرة بـCtrl+V لمراجعة فورية."},{"question":"هل يمكنني مراجعة الأبعاد دون تنزيل أي برنامج؟","answer":"نعم، يعمل الفاحص بالكامل في متصفحك، على الحاسوب والهاتف. لا شيء للتثبيت ولا حساب للإنشاء، وملفاتك لا تُرفع أبدًا إلى خادم."},{"question":"لماذا يقول Windows إن صورتي بحجم ويقول الفاحص حجمًا آخر؟","answer":"مستكشف Windows يعرض أحيانًا أبعادًا مدورة أو مقيسة للعرض، وبعض التطبيقات تُظهر الحجم بعد تطبيق ضبط DPI. ويقرأ الفاحص العرض والارتفاع الحقيقيين بالبكسلات من بيانات الصورة مباشرة."},{"question":"ما عرض أدنى جيد لصور المنتج؟","answer":"يعتمد على المنصة، لكن معظم الأسواق تريد 1000 بكسل على الأقل في أطول جانب ليستطيع المشترون التكبير. وراجع دائمًا قواعد السوق المحدد الحالية قبل الرفع، ثم تحقق من كل صورة مقابلها."},{"question":"هل يستطيع الفاحص قراءة أبعاد لقطة ألصقها؟","answer":"نعم، انسخ لقطة الشاشة واضغط Ctrl+V في الأداة، فيقرأ أبعادها بالبكسلات فورًا. وهذه أسرع طريقة للتحقق من حجم لقطة شاشة قبل إرسالها إلى شخص آخر."},{"question":"ماذا أفعل إذا كانت صورتي أصغر من الحجم المطلوب؟","answer":"اطلب أولًا الملف الأصلي بحجم أكبر، لأن التكبير يخترع بكسلات وينعّم الصورة. وإذا لم يوجد مصدر أكبر، غيّر حجمها بمغيّر حجم الصور واقبل مقايضة الجودة، وأعد المراجعة بعدها."}];
